import type { Middleware } from "@floating-ui/react";

export const centerFloatingMiddleware: Middleware = {
  name: "center",
  fn: ({ rects }) => ({
    x: rects.reference.x + rects.reference.width / 2 - rects.floating.width / 2,
    y:
      rects.reference.y +
      rects.reference.height / 2 -
      rects.floating.height / 2,
  }),
};
