import { type TeamHuntState } from "@hunt/public-client";
import { type ResolvedCutsceneContent } from "@hunt/puzzle-components";
import React from "react";
import { hydrateRoot } from "react-dom/client";
import useDataset from "../../../client/useDataset";
import AlphabetBody from "./AlphabetBody";
import { type AlphabetState } from "./types";

const AlphabetManager = ({
  initialState,
  initialTeamState,
  cutsceneContent,
}: {
  initialState: AlphabetState;
  initialTeamState: TeamHuntState;
  cutsceneContent: ResolvedCutsceneContent[];
}) => {
  const state = useDataset("land_of_no_name", undefined, initialState);
  const teamState = useDataset("team_state", undefined, initialTeamState);
  return (
    <AlphabetBody
      state={state}
      teamState={teamState}
      cutsceneContent={cutsceneContent}
    />
  );
};

const elem = document.getElementById("land-of-no-name-root");
if (elem) {
  const state = (
    window as unknown as { initialLandOfNoNameState: AlphabetState }
  ).initialLandOfNoNameState;
  const teamState = (window as unknown as { initialTeamState: TeamHuntState })
    .initialTeamState;
  const cutsceneContent = (
    window as unknown as { initialCutsceneContent: ResolvedCutsceneContent[] }
  ).initialCutsceneContent;
  hydrateRoot(
    elem,
    <AlphabetManager
      initialState={state}
      initialTeamState={teamState}
      cutsceneContent={cutsceneContent}
    />,
  );
} else {
  console.error(
    "Could not mount Land of No Name Manager because #land-of-no-name-root was nowhere to be found",
  );
}
