import {
  autoUpdate,
  flip,
  offset,
  safePolygon,
  shift,
  useFloating,
  useFocus,
  useHover,
  useInteractions,
  useRole,
} from "@floating-ui/react";
import {
  ALPHABET_LETTER_TO_SLUG,
  ALPHABET_META_SLUG,
  getLetterForSlug,
} from "@hunt/alpha-round";
import { type TeamHuntState } from "@hunt/public-client";
import {
  type ResolvedCutsceneContent,
  CutsceneDisplay,
} from "@hunt/puzzle-components";
import { PUZZLES, getPuzzleTitle } from "@hunt/puzzles";
import { Button, ButtonSecondary, cn } from "@hunt/styled-ui";
import React, { useMemo, useRef, useState, type CSSProperties } from "react";
import {
  PuzzleIcon,
  usePuzzleState,
} from "../../../components/PuzzleAndTaskDisplay/PuzzleCard";
import RoundHintLink from "../../../components/RoundHintLink";
import StyledDialog, { DialogActions } from "../../../components/StyledDialog";
import {
  TeamStateProvider,
  useTeamState,
} from "../../../components/TeamStateProvider";
import { PuzzleTooltipComponent } from "../../../components/Tooltip";
import {
  resetLandOfNoNameProgress,
  revealAllLandOfNoNameLetters,
  useLandOfNoNameLettersState,
} from "../../../components/alphabet/landOfNoNameLocalState";
import {
  mergeSolvedAnswer,
  useSolvedPuzzlesState,
} from "../../../components/puzzleSolveLocalState";
import { centerFloatingMiddleware } from "../../../utils/floating";
import { IS_STATIC_SITE } from "../../../utils/staticSite";
import { useHydrated } from "../../../utils/useHydrated";
import alphabetBg from "./assets/background.png";
import type { AlphabetState, AlphabetPuzzleDisplay } from "./types";

const TILE_COUNT = 26;
const RADIUS = 240;
const TILE_WIDTH = 78; // Your actual tile width
const TILE_HEIGHT = (TILE_WIDTH * 250) / 207; // Your actual tile height

export const CircledTiles: React.FC<{
  puzzles: AlphabetPuzzleDisplay[];
}> = ({ puzzles }) => {
  const containerSize = RADIUS * 2 + Math.max(TILE_WIDTH, TILE_HEIGHT) * 2;
  const meta = puzzles.find(
    (puzzle) => puzzle.puzzle.slug === ALPHABET_META_SLUG,
  );
  const feeders = puzzles.filter(
    (puzzle) => puzzle.puzzle.slug !== ALPHABET_META_SLUG,
  );

  return (
    <div
      className="relative mx-auto"
      style={{
        width: containerSize,
        height: containerSize,
      }}
    >
      {meta && (
        <AlphabetMapEntity
          puzzleDisplay={meta}
          className="absolute transition-transform duration-300"
          style={{
            left: "50%",
            top: "50%",
            width: RADIUS * 2,
            height: RADIUS * 2,
            transform: "translate(-50%, -50%)",
          }}
        />
      )}

      {/* Tiles */}
      {feeders.map((feeder, i) => {
        const angle = (2 * Math.PI * i) / TILE_COUNT - Math.PI / 2;
        // Distance from center to tile center, so tiles are tangent by their height
        const distance = RADIUS + TILE_HEIGHT / 2 - 20;
        const x =
          containerSize / 2 + distance * Math.cos(angle) - TILE_WIDTH / 2;
        const y =
          containerSize / 2 + distance * Math.sin(angle) - TILE_HEIGHT / 2;
        // Face outward
        const transform = `rotate(${(angle * 180) / Math.PI + 90}deg)`;
        return (
          <AlphabetMapEntity
            key={i}
            puzzleDisplay={feeder}
            className="absolute z-10 transition-transform duration-300"
            style={{
              left: x,
              top: y,
              width: TILE_WIDTH,
              height: TILE_HEIGHT,
              transform,
            }}
          />
        );
      })}
    </div>
  );
};

const AlphabetBody = ({
  state,
  teamState,
  cutsceneContent,
}: {
  state: AlphabetState;
  teamState: TeamHuntState;
  cutsceneContent?: ResolvedCutsceneContent[];
}) => {
  const hydrated = useHydrated();
  const { solvedLetters, showAllLetters } = useLandOfNoNameLettersState();
  const { solvedMap } = useSolvedPuzzlesState();
  const dialogRef = useRef<HTMLDialogElement>(null);

  const effectiveSolvedLetters = useMemo(
    () => (hydrated ? solvedLetters : []),
    [hydrated, solvedLetters],
  );
  const effectiveShowAllLetters = hydrated ? showAllLetters : false;
  const effectiveSolvedMap = useMemo(
    () => (hydrated ? solvedMap : {}),
    [hydrated, solvedMap],
  );
  const solvedLetterSet = useMemo(
    () => new Set(effectiveSolvedLetters.map((letter) => letter.toUpperCase())),
    [effectiveSolvedLetters],
  );
  const revealedLetters = useMemo(() => {
    if (effectiveShowAllLetters) {
      return Object.keys(ALPHABET_LETTER_TO_SLUG).sort();
    }
    return Array.from(solvedLetterSet).sort();
  }, [effectiveShowAllLetters, solvedLetterSet]);
  const lettersLabel = useMemo(() => {
    if (revealedLetters.length === 0) {
      return "None";
    }
    return revealedLetters.join(", ");
  }, [revealedLetters]);
  const availableLetters = useMemo(() => {
    if (effectiveShowAllLetters) {
      return Object.keys(ALPHABET_LETTER_TO_SLUG);
    }
    return Array.from(solvedLetterSet);
  }, [effectiveShowAllLetters, solvedLetterSet]);
  const teamStateWithOverride = useMemo(
    () =>
      ({
        ...teamState,
        alpha_available_letters_override: availableLetters,
      }) as TeamHuntState & { alpha_available_letters_override?: string[] },
    [availableLetters, teamState],
  );

  const puzzles = useMemo(() => {
    if (!IS_STATIC_SITE) {
      return state.puzzles;
    }
    return state.puzzles.map((puzzle) => {
      const puzzleDef = PUZZLES[puzzle.puzzle.slug];
      const title = puzzleDef
        ? getPuzzleTitle(puzzleDef, teamStateWithOverride)
        : puzzle.puzzle.title;
      const answer = mergeSolvedAnswer(
        puzzle.puzzle.slug,
        puzzle.puzzle.answer,
        effectiveSolvedMap,
      );
      const letter = getLetterForSlug(puzzle.puzzle.slug);
      const isLetterPuzzle = Boolean(letter && /^[A-Z]$/.test(letter));
      const isSolvedLocal =
        isLetterPuzzle && Boolean(letter && solvedLetterSet.has(letter));
      const shouldReveal = effectiveShowAllLetters || isSolvedLocal;
      const asset = puzzle.assets
        ? shouldReveal
          ? puzzle.assets.solved
          : puzzle.assets.unlocked
        : puzzle.asset;
      return {
        ...puzzle,
        asset,
        puzzle: {
          ...puzzle.puzzle,
          title,
          answer,
        },
      };
    });
  }, [
    solvedLetterSet,
    state.puzzles,
    effectiveSolvedMap,
    teamStateWithOverride,
    effectiveShowAllLetters,
  ]);

  const isLocallySolved = (slug: string) => {
    if (!IS_STATIC_SITE) {
      return false;
    }
    const letter = getLetterForSlug(slug);
    return Boolean(letter && solvedLetterSet.has(letter));
  };

  const showLoading = IS_STATIC_SITE && !hydrated;

  return (
    <TeamStateProvider teamState={teamState}>
      {showLoading ? (
        <div
          id="main-content"
          className="w-screen min-h-[70vh] flex items-center justify-center bg-[#d69f51]"
        >
          <div className="flex flex-col items-center gap-3 text-[#234699]">
            <div className="h-12 w-12 animate-spin rounded-full border-4 border-[#234699] border-t-transparent" />
            <span className="text-sm font-semibold">
              Loading Land of No Name...
            </span>
          </div>
        </div>
      ) : (
        <>
          {/* Separator bar */}
          <div className="w-screen h-8 bg-[#234699]" />

          {/* Top background area with circled tiles */}
          <div
            id="main-content"
            className="relative w-screen aspect-16/9 bg-cover bg-center"
            style={{ backgroundImage: `url(${alphabetBg})` }}
          >
            <div className="absolute right-4 top-12 sm:right-6 z-10">
              {IS_STATIC_SITE ? (
                <button
                  type="button"
                  className="rounded-full border-2 border-[#234699] bg-white/90 px-4 py-2 text-sm font-semibold text-[#234699] shadow hover:bg-white"
                  onClick={() => dialogRef.current?.showModal()}
                >
                  Letters: {revealedLetters.length}/26
                </button>
              ) : (
                <RoundHintLink slug="land_of_no_name" teamState={teamState} />
              )}
            </div>
            <div className="py-10">
              <CircledTiles puzzles={puzzles} />
            </div>
          </div>

          {/* Separator bar */}
          <div className="w-screen h-8 bg-[#234699]" />

          {/* Puzzle list area */}
          <div className="w-screen bg-[#d69f51] p-8">
            <div className="w-full h-full flex justify-center items-center">
              <div className="flex flex-col items-center gap-6 w-full bg-[#eac38b] p-8 rounded-lg">
                {puzzles.map((puzzle) => (
                  <a
                    key={puzzle.puzzle.slug}
                    role="button"
                    href={`/puzzles/${puzzle.puzzle.slug}`}
                    className="flex items-center gap-2 p-2 rounded-lg bg-white/80 hover:bg-white/90 shadow transition text-lg font-semibold text-[#234699] hover:text-black border-2 border-[#234699] hover:border-[#d69f51] w-full max-w-xl"
                  >
                    <div className="flex-1 flex items-center gap-2">
                      <PuzzleIcon
                        lockState={puzzle.puzzle.state}
                        solved={
                          IS_STATIC_SITE
                            ? isLocallySolved(puzzle.puzzle.slug)
                            : !!puzzle.puzzle.answer
                        }
                      />
                      <span className="text-left">{puzzle.puzzle.title}</span>
                    </div>
                    {puzzle.puzzle.answer && (
                      <span className="ml-2 text-green-600 font-bold text-right flex-shrink-0">
                        {puzzle.puzzle.answer}
                      </span>
                    )}
                  </a>
                ))}
              </div>
            </div>
          </div>

          <CutsceneDisplay content={cutsceneContent} />
          {IS_STATIC_SITE && hydrated && (
            <StyledDialog
              ref={dialogRef}
              onClick={(event) => {
                if (event.target === dialogRef.current) {
                  dialogRef.current?.close();
                }
              }}
            >
              <h1 className="text-xl font-semibold text-[#234699] mb-2">
                Alphabet Letters
              </h1>
              <p className="text-sm text-[#234699]">
                Letters revealed: {lettersLabel}
              </p>
              <DialogActions>
                <Button
                  onClick={() => {
                    revealAllLandOfNoNameLetters();
                    dialogRef.current?.close();
                  }}
                >
                  Solve all puzzles and reveal all letters
                </Button>
                <ButtonSecondary
                  onClick={() => {
                    resetLandOfNoNameProgress();
                    dialogRef.current?.close();
                  }}
                >
                  Reset to 0/26
                </ButtonSecondary>
              </DialogActions>
            </StyledDialog>
          )}
        </>
      )}
    </TeamStateProvider>
  );
};

type EntityContainerProps = {
  clickable?: boolean;
  style?: CSSProperties;
  children: React.ReactNode;
  href: string;
  className?: string;
};

const EntityContainer = ({
  style,
  children,
  href,
  className = "",
}: EntityContainerProps) => {
  return (
    <a
      style={style}
      href={href}
      className={cn(
        "block p-0 border-0 bg-transparent absolute cursor-pointer select-none",
        className,
      )}
    >
      {children}
    </a>
  );
};

const AlphabetMapEntity = ({
  puzzleDisplay,
  tooltipChildren,
  style,
  className,
}: {
  puzzleDisplay: AlphabetPuzzleDisplay;
  tooltipChildren?: React.ReactNode;
  className?: string;
  style?: CSSProperties;
}) => {
  const { epoch } = useTeamState();
  const [showTooltip, setShowTooltip] = useState(false);

  const tooltipPosition = puzzleDisplay.tooltip_position ?? "center";
  const isCenterTooltip = tooltipPosition === "center";

  const { refs, floatingStyles, context } = useFloating({
    placement: isCenterTooltip ? "top" : tooltipPosition,
    open: showTooltip,
    onOpenChange: setShowTooltip,
    middleware: isCenterTooltip
      ? [centerFloatingMiddleware, shift()]
      : [offset(5), flip(), shift()],
    whileElementsMounted: autoUpdate,
  });

  const hover = useHover(context, { move: false, handleClose: safePolygon() });
  const focus = useFocus(context);
  const role = useRole(context, { role: "label" });
  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    role,
  ]);

  // Use Tailwind classes for static image properties (w-full, select-none)
  const image = (
    <img
      ref={refs.setReference}
      {...getReferenceProps()}
      src={puzzleDisplay.asset}
      alt={puzzleDisplay.puzzle.title}
      className="w-full select-none pointer-events-auto cursor-pointer transition duration-300 ease-in-out hover:brightness-150 transform-gpu hover:drop-shadow-[0_0_18px_rgba(255,255,255,0.8)]"
    />
  );

  const puzzleStateHandle = usePuzzleState(epoch, puzzleDisplay.puzzle);
  const puzzleState = puzzleStateHandle[0];
  const tooltip = showTooltip && (
    <PuzzleTooltipComponent
      innerRef={refs.setFloating}
      style={{
        ...floatingStyles,
        visibility: "visible",
        zIndex: 100,
      }}
      title={puzzleState.title}
      answer={puzzleState.answer}
      desc={puzzleState.desc}
      lockState={puzzleState.state}
      nsfw={puzzleDisplay.puzzle.nsfw}
      {...getFloatingProps()}
    >
      {tooltipChildren}
    </PuzzleTooltipComponent>
  );

  return (
    <>
      <EntityContainer
        style={style}
        href={`/puzzles/${puzzleState.slug}`}
        className={className}
      >
        {image}
      </EntityContainer>
      {tooltip}
    </>
  );
};

export default AlphabetBody;
