import {
  ALPHABET_LETTER_TO_SLUG,
  ALPHABET_SLUGS,
  getLetterForSlug,
} from "@hunt/alpha-round";
import { PUZZLES } from "@hunt/puzzles";
import { useCallback, useEffect, useState } from "react";
import { clearLocalGuessLogs } from "../puzzleGuessLocalState";
import {
  addSolvedPuzzles,
  removeSolvedPuzzles,
} from "../puzzleSolveLocalState";

const SOLVED_LETTERS_KEY = "hunt.land_of_no_name.solved_letters";
const SHOW_ALL_LETTERS_KEY = "hunt.land_of_no_name.show_all_letters";
const LOCAL_STATE_EVENT = "land-of-no-name-local-state";

const canUseStorage = () =>
  typeof window !== "undefined" && typeof window.localStorage !== "undefined";

const normalizeLetter = (letter: string) => letter.toUpperCase();

const isAlphabetLetter = (letter: string | undefined): letter is string =>
  Boolean(letter && /^[A-Z]$/.test(letter));

const parseStoredLetters = (raw: string | null): string[] => {
  if (!raw) return [];
  try {
    const parsed = JSON.parse(raw) as unknown;
    if (!Array.isArray(parsed)) return [];
    return parsed
      .map((entry) => (typeof entry === "string" ? normalizeLetter(entry) : ""))
      .filter((entry) => isAlphabetLetter(entry));
  } catch {
    return [];
  }
};

const getUniqueLetters = (letters: string[]) =>
  Array.from(new Set(letters.map(normalizeLetter))).filter((entry) =>
    isAlphabetLetter(entry),
  );

const dispatchLocalStateEvent = () => {
  if (typeof window === "undefined") return;
  window.dispatchEvent(new Event(LOCAL_STATE_EVENT));
};

const ALL_ALPHABET_LETTERS = Object.keys(ALPHABET_LETTER_TO_SLUG).sort();
const ALL_ALPHABET_PUZZLE_SLUGS = ALPHABET_SLUGS;

export const getLandOfNoNameSolvedLetters = (): string[] => {
  if (!canUseStorage()) return [];
  try {
    return getUniqueLetters(
      parseStoredLetters(window.localStorage.getItem(SOLVED_LETTERS_KEY)),
    );
  } catch {
    return [];
  }
};

export const setLandOfNoNameSolvedLetters = (letters: string[]) => {
  if (!canUseStorage()) return;
  try {
    const next = getUniqueLetters(letters);
    window.localStorage.setItem(SOLVED_LETTERS_KEY, JSON.stringify(next));
    dispatchLocalStateEvent();
  } catch {
    // Ignore storage failures.
  }
};

export const markLandOfNoNameSolved = (slug: string): boolean => {
  if (!canUseStorage()) return false;
  const letter = getLetterForSlug(slug);
  if (!isAlphabetLetter(letter)) return false;
  const existing = new Set(getLandOfNoNameSolvedLetters());
  if (existing.has(letter)) return false;
  existing.add(letter);
  setLandOfNoNameSolvedLetters(Array.from(existing));
  return true;
};

export const getLandOfNoNameShowAllLetters = (): boolean => {
  if (!canUseStorage()) return false;
  try {
    return window.localStorage.getItem(SHOW_ALL_LETTERS_KEY) === "true";
  } catch {
    return false;
  }
};

export const setLandOfNoNameShowAllLetters = (value: boolean) => {
  if (!canUseStorage()) return;
  try {
    window.localStorage.setItem(SHOW_ALL_LETTERS_KEY, String(value));
    dispatchLocalStateEvent();
  } catch {
    // Ignore storage failures.
  }
};

export const resetLandOfNoNameProgress = () => {
  setLandOfNoNameSolvedLetters([]);
  setLandOfNoNameShowAllLetters(false);
  removeSolvedPuzzles(ALL_ALPHABET_PUZZLE_SLUGS);
  clearLocalGuessLogs(ALL_ALPHABET_PUZZLE_SLUGS);
};

export const revealAllLandOfNoNameLetters = () => {
  setLandOfNoNameSolvedLetters(ALL_ALPHABET_LETTERS);
  setLandOfNoNameShowAllLetters(true);
  addSolvedPuzzles(
    ALL_ALPHABET_LETTERS.map((letter) => {
      const slug = ALPHABET_LETTER_TO_SLUG[letter];
      const answer = PUZZLES[slug]?.answer;
      return { slug, answer };
    }),
  );
};

export const useLandOfNoNameLettersState = () => {
  const [solvedLetters, setSolvedLetters] = useState<string[]>(() =>
    getLandOfNoNameSolvedLetters(),
  );
  const [showAllLetters, setShowAllLettersState] = useState<boolean>(() =>
    getLandOfNoNameShowAllLetters(),
  );

  const syncFromStorage = useCallback(() => {
    setSolvedLetters(getLandOfNoNameSolvedLetters());
    setShowAllLettersState(getLandOfNoNameShowAllLetters());
  }, []);

  useEffect(() => {
    if (!canUseStorage()) return;
    const handleStorage = (event: StorageEvent) => {
      if (
        event.key === SOLVED_LETTERS_KEY ||
        event.key === SHOW_ALL_LETTERS_KEY
      ) {
        syncFromStorage();
      }
    };
    window.addEventListener(LOCAL_STATE_EVENT, syncFromStorage);
    window.addEventListener("storage", handleStorage);
    return () => {
      window.removeEventListener(LOCAL_STATE_EVENT, syncFromStorage);
      window.removeEventListener("storage", handleStorage);
    };
  }, [syncFromStorage]);

  const setShowAllLetters = useCallback(
    (value: boolean) => {
      setShowAllLettersState(value);
      setLandOfNoNameShowAllLetters(value);
    },
    [setShowAllLettersState],
  );

  return {
    solvedLetters,
    showAllLetters,
    setShowAllLetters,
  };
};
